package com.mzmiyazxakii.spin;
import net.minecraft.network.FriendlyByteBuf;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.ItemStack;import net.minecraftforge.network.NetworkEvent;import net.minecraftforge.network.NetworkRegistry;import net.minecraftforge.network.simple.SimpleChannel;import java.util.function.Supplier;
public final class SpinSkinNetwork{private static final String V="1";private static final SimpleChannel C=NetworkRegistry.newSimpleChannel(new ResourceLocation(SpinMod.MOD_ID,"skin_channel"),()->V,V::equals,V::equals);private SpinSkinNetwork(){}public static void register(){C.registerMessage(0,Packet.class,Packet::encode,Packet::decode,Packet::handle);}public static void sendSkin(int s){C.sendToServer(new Packet(s));}private record Packet(int skin){static void encode(Packet p,FriendlyByteBuf b){b.writeVarInt(p.skin);}static Packet decode(FriendlyByteBuf b){return new Packet(b.readVarInt());}static void handle(Packet p,Supplier<NetworkEvent.Context> c){var x=c.get();x.enqueueWork(()->{ServerPlayer pl=x.getSender();if(pl==null)return;int s=Math.max(0,Math.min(1,p.skin));for(int i=0;i<pl.getInventory().getContainerSize();i++){ItemStack st=pl.getInventory().getItem(i);if(st.is(SpinMod.STEEL_BALL.get()))SpinSkinManager.apply(st,s);}pl.getInventory().setChanged();});x.setPacketHandled(true);}}}